.password-field{position:relative;margin-top:7px}.cat-login .password-field input{margin:0;padding-right:52px}.password-toggle{position:absolute;top:50%;right:5px;display:grid;width:40px;height:40px;padding:0;place-items:center;transform:translateY(-50%);border:0;border-radius:8px;background:transparent;color:inherit;cursor:pointer}.password-toggle:hover{background:rgba(15,72,94,.08)}.password-toggle:focus-visible{outline:2px solid var(--primary);outline-offset:1px}.password-toggle svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;stroke-width:2}.password-toggle .eye-off{display:none}.password-toggle[aria-pressed="true"] .eye-on{display:none}.password-toggle[aria-pressed="true"] .eye-off{display:block}
