<section class="content"><div class="wrap"><div class="login-wrap"><div class="cat-login"><?php if(!empty($error)): ?><div class="error"><?= e($error) ?></div><?php endif; ?><form method="post" action="/idemaclima/campus/cat/login"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><label>Email<input name="login" required autocomplete="username"></label><label for="cat-password">Password</label><div class="password-field"><input id="cat-password" type="password" name="password" required autocomplete="current-password"><button class="password-toggle" type="button" aria-label="Mostra password" aria-controls="cat-password" aria-pressed="false"><svg class="eye-on" viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg><svg class="eye-off" viewBox="0 0 24 24" aria-hidden="true"><path d="m3 3 18 18"/><path d="M10.6 5.2A10.8 10.8 0 0 1 12 5c6.5 0 10 7 10 7a17.8 17.8 0 0 1-2.1 3.1M6.2 6.2C3.5 8.1 2 12 2 12s3.5 7 10 7a9.8 9.8 0 0 0 4.1-.9"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg></button></div><button class="btn" type="submit">Accedi</button></form></div><aside class="cat-side"><span class="section-label">— Campus CAT</span><h2>Formazione dedicata alla rete tecnica.</h2><p>Eventi, aggiornamenti e incontri riservati ai Centri Assistenza Tecnica IDEMA.</p><p><a class="btn" href="/idemaclima/campus/cat/registrazione">Richiedi un account personale</a></p></aside></div></div></section>
<script nonce="<?= htmlspecialchars(\App\Core\Security::nonce(), ENT_QUOTES, 'UTF-8') ?>">(()=>{const button=document.querySelector('.password-toggle'),input=document.getElementById('cat-password');if(!button||!input)return;button.addEventListener('click',()=>{const show=input.type==='password';input.type=show?'text':'password';button.setAttribute('aria-pressed',show?'true':'false');button.setAttribute('aria-label',show?'Nascondi password':'Mostra password');input.focus()})})();</script>
